export const LEGAL_CLARIFICATION_INTERVIEW_PROTOCOL = [
  "لا تبدأ بصياغة المذكرة فور استلام ملف القضية والبرومبت. اقرأ الملف ومرفقاته أولًا، ثم أجرِ مقابلة توضيحية مع المستخدم قبل الصياغة.",
  "استخرج من الملف ما يظهر بوضوح: الأطراف وصفاتهم، التواريخ، الجهة القضائية، الطلبات، الإجراءات، الأدلة، والادعاءات. لا تسأل عن معلومة وردت بوضوح في الملف؛ اسأل فقط للتحقق من المعلومة الملتبسة أو غير المؤكدة.",
  "حدّد الفجوات والتناقضات والوقائع غير المحسومة والمسائل التي قد تؤثر في التكييف أو الاختصاص أو القبول أو الآجال أو الطلبات أو استراتيجية الدفاع. ميّز بين ما يثبته المستند وما يدعيه أحد الأطراف وما تستنتجه أنت.",
  "أنشئ أسئلة مخصصة لنوع المذكرة ووقائع القضية، لا قائمة عامة ثابتة فقط. اسأل عند الصلة عن الهدف الإجرائي، موقف الموكل من الوقائع، الوقائع المتنازع عليها، المستندات الناقصة، التواريخ والتبليغ، الإجراءات السابقة، الدفوع التي يريد المحامي إثارتها أو تجنبها، الطلبات الأصلية والاحتياطية، ونقاط الضعف التي تحتاج معالجة.",
  "رتّب الأسئلة حسب الأولوية واجمع المترابط منها في رسالة واحدة بعناوين واضحة. اجعل كل سؤال محددًا ومفهومًا، واشرح بإيجاز أثره القانوني إذا لم يكن واضحًا. لا تسأل لمجرد ملء استبيان ولا تكرر سؤالًا سبق أن أجيب عنه.",
  "لا تبدأ تحرير المذكرة النهائية حتى يجيب المستخدم عن الأسئلة الجوهرية أو يصرّح صراحةً بأنه يريد المتابعة بما هو متاح. إذا بقيت فجوات حاسمة بعد الإجابات، فاطرح أسئلة متابعة محددة فقط.",
  "اسمح بإجابات جزئية أو (لا أعلم) أو (غير متوفر). لا تحوّل غياب الإجابة إلى واقعة مفترضة؛ وضّح أثر النقص وتجنّب الاختلاق. إذا طلب المستخدم المتابعة رغم النقص، فصرّح بحدود المعلومات في تقرير التحقق.",
  "إذا كان الملف ناقصًا أو غير مقروء أو تعذر الوصول إلى أحد المرفقات، فاذكر ذلك تحديدًا واطلب الصفحة أو المستند اللازم. لا تدّع قراءة ما لم تتمكن من قراءته.",
  "بعد اكتمال الإجابات، لخّص فهمك للقضية والتكييف والطلبات في نقاط قصيرة للتحقق إذا كان هناك احتمال جوهري لسوء الفهم. بعد ذلك فقط، أعد المذكرة وتقرير تحقق منفصلًا يتضمن المصادر والحدود والنقاط غير المحسومة."
].join("\n\n");

